    public static IReadOnlyCollection<string> Keys => Catalog["es"].Keys.Concat(EnumCatalog["es"].Keys)
        .Distinct(StringComparer.Ordinal).ToArray();

    public static bool ContainsKey(string key) => Catalog["es"].ContainsKey(key) || EnumCatalog["es"].ContainsKey(key);

    public static bool TryTranslate(string locale, string key, out string text)
    {
        if (Catalog.TryGetValue(locale, out var language) && language.TryGetValue(key, out var translated))
        {
            text = translated;
            return true;
        }
        if (EnumCatalog.TryGetValue(locale, out var enumLanguage) && enumLanguage.TryGetValue(key, out translated))
        {
            text = translated;
            return true;
        }
        text = "";
        return false;
    }

    private static IReadOnlyDictionary<string, string> Map(params (string Key, string Text)[] entries) =>
        new ReadOnlyDictionary<string, string>(entries.ToDictionary(entry => "sessionPreferences." + entry.Key,
            entry => entry.Text, StringComparer.Ordinal));

    private static IReadOnlyDictionary<string, string> MapEnums(params (string Key, string Text)[] entries) =>
        new ReadOnlyDictionary<string, string>(entries.ToDictionary(entry => "sessionPreferences.enum." + entry.Key,
            entry => entry.Text, StringComparer.Ordinal));
}
